from openpyxl import load_workbook
from openpyxl.utils import get_column_letter

# Load the workbook and select the sheet
wb = load_workbook('input.xlsx')
ws = wb['Sheet1']

# Step 1: Find the row with 'BR1 Sales' in Column C
br1_sales_row = None
for row in ws.iter_rows(min_col=3, max_col=3):
    for cell in row:
        if cell.value == 'BR1 Sales':
            br1_sales_row = cell.row
            break
    if br1_sales_row:
        break

# Step 2: Calculate the sum of values in Column D for rows where Column E contains a zero
sum_zero_rows = 0
zero_rows = []
for row in ws.iter_rows(min_row=2, min_col=5, max_col=5):
    for cell in row:
        if cell.value == 0:
            zero_rows.append(cell.row)
            sum_zero_rows += ws[get_column_letter(4) + str(cell.row)].value

# Step 3: Insert the sum into Column D next to the row containing 'BR1 Sales'
if br1_sales_row:
    col_d = get_column_letter(4)
    ws[f"{col_d}{br1_sales_row}"] = sum_zero_rows

# Step 4: Delete all rows where Column E contains a zero except for the rows where the reference contains 'BR1 Sales'
rows_to_delete = []
for row in zero_rows:
    if row != br1_sales_row:
        rows_to_delete.append(row)

# Delete rows in reverse order to avoid shifting issues
for row in reversed(rows_to_delete):
    ws.delete_rows(row)

# Step 5: Delete blank lines (rows with all empty cells)
rows_to_delete = []
for row in range(1, ws.max_row + 1):
    is_empty = True
    for cell in ws[row]:
        if cell.value is not None:
            is_empty = False
            break
    if is_empty:
        rows_to_delete.append(row)

# Delete blank rows in reverse order
for row in reversed(rows_to_delete):
    ws.delete_rows(row)

# Save the modified workbook
wb.save('output.xlsx')
