    if row[0] == 'National TV' and row[1] == 'India':
        # Find the row in the sheet
        for cell in main_sheet.iter_rows(min_row=2):
            if cell[0].value == row[0] and cell[1].value == row[1]:
                # Update the 'Bill Rate of Resource' (column G)
                main_sheet[cell[6].column - 1][cell[0].row - 1].value = 180
                break

# Step 4: Insert two new rows immediately following each row where the Company is 'Ahmed Sons'
# We need to process the rows in reverse to avoid shifting issues
ahmed_sons_rows = []
for row in main_sheet.iter_rows(min_row=2, values_only=True):
    if row[0] == 'Ahmed Sons':
        ahmed_sons_rows.append(row[0])

# Insert the rows in reverse order to avoid shifting issues
for row_num in reversed(ahmed_sons_rows):
    main_sheet.insert_rows(row_num + 1)

# Step 5: Perform VLOOKUP to populate Column M with 'working Weeks' from Lookup sheet
# Create a dictionary for quick lookup
lookup_dict = {}
for row in lookup_sheet.iter_rows(min_row=2, values_only=True):
    if row[0] is not None:
        lookup_dict[row[0]] = row[1]

# Update the 'Lookup For Working Weeks' column (column M)
