    employee_id = row[2]  # Column C
    if employee_id in lookup_dict:
        # Find the row in the sheet
        for cell in main_sheet.iter_rows(min_row=2):
            if cell[2].value == employee_id:
                # Update the 'Lookup For Working Weeks' (column M)
                main_sheet[cell[12].column - 1][cell[0].row - 1].value = lookup_dict[employee_id]
                break

# Now, delete the rows that were marked for deletion
for row_num in reversed(rows_to_delete):
    main_sheet.delete_rows(row_num)

