        if current_group is None:
            current_group = [row]
        else:
            current_group.append(row)
    else:
        if current_group is not None:
            # Check if the group has at least 2 cells
            if len(current_group) >= 2:
                total += len(current_group)
            current_group = None

# After the loop, check if there's a remaining group
if current_group is not None:
    if len(current_group) >= 2:
        total += len(current_group)

# Write the computed total to the answer range (B15:E15)
for col in range(2, 6):  # Columns B to E (indices 2 to 5)
    ws.cell(row=15, column=col).value = total

