    name, hd, sd, _, _, status = row
    # Skip empty rows
    if not name:
        continue

    # Initialize the name in the results if not already present
    if name not in results:
        results[name] = {'HD': 0, 'SD': 0}

    # Iterate through Sheet1 to find matching entries
    for row1 in sheet1_sheet.iter_rows(min_row=2, values_only=True):
        status1, name1, type1, amount1 = row1
        if name1 == name and (status1 == 'Completed' or status1 == 'Not Completed'):
            if type1 == 'HD':
                results[name]['HD'] += amount1
            elif type1 == 'SD':
                results[name]['SD'] += amount1

# Write the results to the Summary sheet
for i, (name, data) in enumerate(results.items()):
    summary_sheet[f'A{i + 2}'] = name
    summary_sheet[f'B{i + 2}'] = data['HD']
    summary_sheet[f'C{i + 2}'] = data['SD']

