    if any(cell.value for cell in row):
        agent_categories_end = row[0].row
    else:
        break

# Find the end of the agent schedule
agent_schedule_end = None
for row in ws.iter_rows(min_row=13, min_col=4, max_col=19):
    if any(cell.value for cell in row):
        agent_schedule_end = row[0].row
    else:
        break

# Find the end of the total count
total_count_end = None
for row in ws.iter_rows(min_row=22, min_col=4, max_col=19):
    if any(cell.value for cell in row):
        total_count_end = row[0].row
    else:
        break

# Initialize the total count table
total_count = {}

# Iterate over each category
for row in ws.iter_rows(min_row=4, min_col=4, max_row=agent_categories_end):
    category = row[0].value
    if category:
        total_count[category] = [0] * (agent_schedule_end - 13 + 1)

# Iterate over each agent in the agent schedule
for row in ws.iter_rows(min_row=13, min_col=4, max_row=agent_schedule_end):
    agent = row[0].value
    for col in range(1, len(row)):
        if row[col].value == 1:
            # Find the category for this agent
            for cat_row in ws.iter_rows(min_row=4, min_col=4, max_row=agent_categories_end):
                if cat_row[0].value == agent:
                    for cat_col in range(1, len(cat_row)):
                        if cat_row[cat_col].value == 1:
                            category = ws.cell(row=cat_row[0].row, column=cat_col + 1).value
                            if category in total_count:
                                total_count[category][col - 1] += 1

# Write the results to the total count table
for i, (category, counts) in enumerate(total_count.items()):
    ws[f'E{22 + i}'] = category
    for j, count in enumerate(counts):
        ws[get_column_letter(6 + j + 1) + f'{22 + i}'] = count

# Save the workbook
wb.save('output.xlsx')
