# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Initialize a dictionary to store the average turnaround times for each department
department_averages = {}

# Iterate through the rows in the data (excluding the header)
for row in ws.iter_rows(min_row=2, max_col=3, values_only=True):
    department, status, turnaround_time = row
    if department and status and turnaround_time:
        # Check if the status is "In Progress" or "In Review" and turnaround time is >= 6
        if status in ["In Progress", "In Review"] and turnaround_time >= 6:
            if department not in department_averages:
                department_averages[department] = {"total": 0, "count": 0}
            department_averages[department]["total"] += turnaround_time
            department_averages[department]["count"] += 1

# Write the computed averages to the specified range (B11:B13)
for i, (department, data) in enumerate(department_averages.items()):
    if i < 3:  # Only write for the first 3 departments (A, B, C)
        average = data["total"] / data["count"] if data["count"] > 0 else ""
        ws[f"B{10 + i + 1}"] = average

# Save the modified workbook
wb.save('output.xlsx')
